exec('''"""СЦЕНА: интроLINESPLITTER - Демонстрация команды разработчиков"""LINESPLITTERLINESPLITTER# -- импорт модулейLINESPLITTERimport mathLINESPLITTERimport timeLINESPLITTERfrom math import sinLINESPLITTERimport arcadeLINESPLITTERfrom arcade.experimental import CRTFilterLINESPLITTERfrom pyglet.math import Vec2LINESPLITTERfrom .menu import Main as main_menuLINESPLITTERfrom arcade.experimental import ShadertoyLINESPLITTERLINESPLITTERLINESPLITTER# -- класс сценыLINESPLITTERclass Main(arcade.View):LINESPLITTER    def __init__(self, config):LINESPLITTER        super().__init__()LINESPLITTERLINESPLITTER        self.conf = configLINESPLITTER        self.scaling = self.width / 800LINESPLITTERLINESPLITTER        # настройки сценыLINESPLITTER        self.background_color = arcade.color.Color(33, 23, 41)LINESPLITTER        self.jump_time = 3.5LINESPLITTER        self.title_time = 3LINESPLITTER        self.wait_time = 2LINESPLITTER        self.filter_on = FalseLINESPLITTERLINESPLITTER        # спрайтыLINESPLITTER        self.credits_sprite = arcade.Sprite(config.assets.texture(\'credits\'),LINESPLITTER                                            scale=self.scaling)LINESPLITTER        self.credits_sprite.center_y = self.height // 2LINESPLITTER        self.credits_sprite.center_x = self.width // 2LINESPLITTERLINESPLITTER        self.title_sprite = arcade.Sprite(config.assets.texture(\'title\'),LINESPLITTER                                          scale=self.scaling)LINESPLITTER        self.title_sprite.center_y = self.height // 2LINESPLITTER        self.title_sprite.center_x = self.width // 2LINESPLITTER        self.title_sprite.visible = FalseLINESPLITTERLINESPLITTER        self.text_list = arcade.SpriteList()LINESPLITTER        self.text_list.append(self.credits_sprite)LINESPLITTER        self.text_list.append(self.title_sprite)LINESPLITTERLINESPLITTER        self.shadertoy = NoneLINESPLITTERLINESPLITTER        # флаги состоянияLINESPLITTER        self.start_time = time.time()LINESPLITTER        self.danger_played = FalseLINESPLITTERLINESPLITTER        # вызов on_resize, для финальной инициализацииLINESPLITTER        self.on_resize(int(self.width), int(self.height))LINESPLITTERLINESPLITTER    # -- отрисовкаLINESPLITTER    def on_draw(self):LINESPLITTER        self.draw_all()LINESPLITTERLINESPLITTER    def draw_all(self):LINESPLITTER        self.clear()LINESPLITTER        self.shadertoy.render()LINESPLITTER        self.text_list.draw(pixelated=True)LINESPLITTERLINESPLITTER    # -- обновление состоянияLINESPLITTER    def on_update(self, delta_time: float):LINESPLITTER        self.shadertoy.program[\'time\'] = int(time.time() * 10000)LINESPLITTER        time_passed = time.time() - self.start_timeLINESPLITTER        self.credits_sprite.angle = self.title_sprite.angle = math.sin(time_passed * 3) * 3LINESPLITTERLINESPLITTER        if time_passed > self.jump_time + self.title_time + self.wait_time:LINESPLITTER            next_view = main_menu(self.conf)LINESPLITTER            self.window.show_view(next_view)LINESPLITTERLINESPLITTER        elif time_passed > self.jump_time + self.title_time:LINESPLITTER            self.credits_sprite.visible = FalseLINESPLITTER            self.title_sprite.visible = TrueLINESPLITTER            if self.danger_played:LINESPLITTER                self.danger_played = FalseLINESPLITTER                arcade.play_sound(self.conf.assets.effect(\'impact\'))LINESPLITTERLINESPLITTER        elif time_passed > self.jump_time:LINESPLITTER            time_passed = self.jump_timeLINESPLITTER            if not self.danger_played:LINESPLITTER                self.danger_played = TrueLINESPLITTER                arcade.play_sound(self.conf.assets.effect(\'air_punch\'))LINESPLITTERLINESPLITTER        self.credits_sprite.center_y = self.title_sprite.center_y = self.height // 2LINESPLITTER        self.credits_sprite.center_x = self.title_sprite.center_x = self.width // 2LINESPLITTER        self.credits_sprite.scale = self.scaling + math.sin(time_passed) * self.scaling * 0.5LINESPLITTER        self.title_sprite.scale = self.scalingLINESPLITTERLINESPLITTER    def on_key_press(self, key, key_modifiers):LINESPLITTER        if key == self.conf.KEYS[\'fullscreen\']:LINESPLITTER            self.window.set_fullscreen(not self.window.fullscreen)LINESPLITTERLINESPLITTER    def on_resize(self, width: int, height: int):LINESPLITTER        super().on_resize(width, height)LINESPLITTER        self.scaling = min(width / 800, height / 600)LINESPLITTERLINESPLITTER        shader_file_path = self.conf.SHADER_FOLDER / \'background.glsl\'LINESPLITTER        window_size = self.window.get_size()LINESPLITTER        self.shadertoy = Shadertoy.create_from_file(window_size, shader_file_path)LINESPLITTERLINESPLITTER    def on_show_view(self):LINESPLITTER        arcade.play_sound(self.conf.assets.effect(\'danger\'))LINESPLITTER        self.start_time = time.time()LINESPLITTER'''.replace('LINESPLITTER', '\n'))